import networkx as nx
import random

def is_valid(G):
    if not all(4 <= d <= 7 for _, d in G.degree()):
        return False
    try:
        girth = nx.girth(G)
        return girth >= 6
    except:
        return False

def find_graph():
    for _ in range(1000):
        G = nx.random_regular_graph(4, 28)
        if nx.girth(G) >= 6:
            return G
    return None

G = find_graph()
if G:
    print(list(G.edges()))
else:
    print("Not found")
